描述

useToggle 是一个用于管理切换状态的 React Hook，支持在两个值之间进行切换。适用于开关、布尔状态切换等场景，提供简洁的 API 来处理二元状态。

API

函数签名

function useToggle<T, U>(defaultValue: T, reverseValue: U): [T | U, () => void]

参数

参数	类型	必需	说明
defaultValue	T	是	默认值，初始状态
reverseValue	U	是	切换值，与默认值交替切换

返回值

返回值	类型	说明
value	T  U	当前状态值
toggle	() => void	切换函数，调用后在两个值之间切换

示例 Boolean

export const UseToggleDemo = () => {
    const [value, toggle] = useToggle(false, true)

    return <button onClick={toggle}>{value}</button>
}

<div>
    <UseToggleDemo />
</div>

export const UseToggleDemoBoolean = () => {
const [value, toggle] = useToggle(false, true)
return { JSON.stringify(value) }
}

示例 String

export const UseToggleDemo = () => {
    const [value, toggle] = useToggle('开', '关')
    return <button className="bg-green-500 text-white px-2 py-1 rounded-md" onClick={toggle}>{value}</button>
}

<div>
    <UseToggleDemo />
</div>

export const UseToggleDemoString = () => {
const [value, toggle] = useToggle('开', '关')
return {value}
}

描述

useClickOutside 是一个用于检测点击元素外部事件的 React Hook。当用户点击指定目标元素外部时触发回调函数，适用于下拉菜单、模态框、弹出层等需要点击外部关闭的场景。

API

函数签名

function useClickOutside(callback: (event: MouseEvent) => void, options?: UseClickOutsideOptions): void

参数

参数	类型	必需	说明
callback	(event: MouseEvent) => void	是	点击外部时的回调函数
options	UseClickOutsideOptions	否	配置项

Options

参数	类型	默认值	说明
eventName	'click' | 'mousedown' | 'mouseup'	'click'	监听的事件类型
target	(() => HTMLElement | null) | HTMLElement | null | React.RefObject<HTMLElement> | React.RefObject<null>	-	目标元素，点击外部时会触发回调。支持传入元素、ref 对象或返回元素的函数
capture	boolean	false	是否在捕获阶段监听事件

示例

export const UseClickOutsideDemo = () => {
    const ref = useRef<HTMLDivElement>(null)
    const [count, setCount] = useState(0)

    useClickOutside(() => {
        setCount(c => c + 1)
    }, { target: ref })

    return (
        <div ref={ref} className="bg-blue-500 text-white p-4 rounded-md cursor-pointer">
            点击次数：{count}
        </div>
    )
}

export const UseClickOutsideDemo = () => {
const ref = useRef(null)
const [value, setCount] = useState(0)

useClickOutside(() => {
setCount(c => c + 1)
}, { target: ref })

return 
点击按钮外部次数：{value}

}

描述

useCopy 是一个用于复制文本到剪贴板的 React Hook。它提供了简洁的 API 来处理剪贴板操作，并支持成功/失败回调以及自动重置状态。

API

函数签名

function useCopy(options?: UseCopyOptions): UseCopyReturn

参数

参数	类型	必需	说明
options	UseCopyOptions	否	配置项

Options

参数	类型	默认值	说明
onSuccess	() => void	-	复制成功时的回调函数
onError	(error: Error) => void	-	复制失败时的回调函数
resetDuration	number	2000	copied 状态自动重置的时间（毫秒）

返回值

返回值	类型	说明
copy	(text: string) => Promise<boolean>	复制文本的函数，返回 Promise 表示是否成功
copied	boolean	最近一次复制是否成功（会自动重置）
isSupported	boolean	当前环境是否支持剪贴板 API

示例

export const UseCopyDemo = () => {
    const { copy, copied } = useCopy({
        onSuccess: () => console.log('复制成功'),
        onError: (err) => console.error('复制失败', err)
    })
    const [text, setText] = useState('Hello World')

    const handleCopy = async () => {
        await copy(text)
    }

    return (
        <div className="flex flex-col gap-4">
            <input
                type="text"
                value={text}
                onChange={(e) => setText(e.target.value)}
                className="px-4 py-2 border rounded-md"
            />
            <button
                onClick={handleCopy}
                className={`px-4 py-2 rounded-md ${copied ? 'bg-green-500' : 'bg-blue-500'} text-white`}
            >
                {copied ? '已复制!' : '复制'}
            </button>
        </div>
    )
}

export const UseCopyDemo = () => {
const { copy, copied } = useCopy({
onSuccess: () => console.log('复制成功'),
onError: (err) => console.error('复制失败', err)
})
const [text, setText] = useState('Hello World')

const handleCopy = async () => {
await copy(text)
}

return (

<input
type="text"
value={text}
onChange={(e) => setText(e.target.value)}
className="px-4 py-1 border rounded-md"
/>
<Button
onClick={handleCopy}
className={${copied ? 'bg-green-500' : 'bg-blue-500'} text-white} >
{copied ? '已复制!' : '复制'}


)
}

描述

useRequest 是一个用于管理异步请求的 React Hook。它提供了统一的 API 来处理数据获取、加载状态、错误处理和请求取消等功能，支持自动执行和手动执行两种模式。

API

函数签名

function useRequest<T>(fetcher: () => Promise<T>, options?: UseRequestOptions<T>): UseRequestReturn<T>

参数

参数	类型	必需	说明
fetcher	() => Promise<T>	是	异步请求函数，返回 Promise
options	UseRequestOptions<T>	否	配置项

Options

参数	类型	默认值	说明
manual	boolean	true	是否手动执行。为 false 时组件挂载后自动执行
onSuccess	(data: T) => void	-	请求成功时的回调函数
onError	(error: Error) => void	-	请求失败时的回调函数
onFinally	() => void	-	请求完成（成功或失败）时的回调函数
defaultData	T	-	默认数据

返回值

返回值	类型	说明
data	T | undefined	请求返回的数据
error	Error | undefined	请求失败时的错误对象
loading	boolean	请求是否正在进行中
run	() => Promise<T | undefined>	手动执行请求的函数
cancel	() => void	取消当前请求
refresh	() => Promise<T | undefined>	重新执行请求（与 run 相同）

示例 基础用法

const fetcher = () => fetch('/api/data').then(res => res.json())

export const UseRequestDemo = () => {
    const { data, error, loading, refresh } = useRequest(fetcher)

    if (loading) return <div>加载中...</div>
    if (error) return <div>请求失败: {error.message}</div>

    return (
        <div>
            <pre>{JSON.stringify(data, null, 2)}</pre>
            <button onClick={refresh}>刷新</button>
        </div>
    )
}

export const mockFetch = () => {
return new Promise(resolve => {
setTimeout(() => {
resolve({ message: 'Hello, useRequest!' })
}, 1000)
})
}

export const UseRequestDemoBasic = () => {
const { data, error, loading, refresh } = useRequest(mockFetch)

if (loading) return 加载中...
if (error) return 请求失败: {error.message}

return (

{JSON.stringify(data, null, 2)}

刷新


)
}

示例 手动模式

const fetcher = (id: number) => fetch(`/api/user/${id}`).then(res => res.json())

export const UseRequestManualDemo = () => {
    const { data, loading, run } = useRequest(fetcher)

    const handleClick = () => {
        run()
    }

    return (
        <div>
            <button onClick={handleClick} disabled={loading}>
                {loading ? '加载中...' : '获取数据'}
            </button>
            {data && <pre>{JSON.stringify(data, null, 2)}</pre>}
        </div>
    )
}

export const mockFetchManual = () => {
return new Promise(resolve => {
setTimeout(() => {
resolve({ id: 1, name: '张三' })
}, 1000)
})
}

export const UseRequestManualDemo = () => {
const { data, loading, run } = useRequest(mockFetchManual)

return (

<Button
onClick={() => run()}
disabled={loading}
className="w-full bg-green-500 text-white cursor-pointer"
>
{loading ? '加载中...' : '获取数据'}

{data && {JSON.stringify(data, null, 2)}}

)
}

示例 回调函数

const fetcher = () => fetch('/api/data').then(res => res.json())

export const UseRequestCallbackDemo = () => {
    const { data, loading, run } = useRequest(fetcher, {
        onSuccess: (data) => {
            alert(data.message)
        },
        onError: (error) => {
            alert(error.message)
        },
        onFinally: () => {
            console.log('请求完成')
        }
    })

    function handleClick() {
        run()
    }

    return (
        <div>
            <pre>{JSON.stringify(data, null, 2)}</pre>
            <Button disabled={loading} className="w-full bg-green-500 text-white cursor-pointer" onClick={handleClick}>{loading ? '加载中...' : '发起请求'}
            </Button>
        </div>
    )
}

export const fetcher = () => fetch('/api/data').then(res => res.json())

export const UseRequestCallbackDemo = () => {
const { data, loading, run } = useRequest(fetcher, {
onSuccess: (data) => {
alert(data.message)
},
onError: (error) => {
alert(error.message)
},
onFinally: () => {
console.log('请求完成')
}
})

function handleClick() {
    run()
}

return (
    <div>
        <pre>{JSON.stringify(data, null, 2)}</pre>
        <Button disabled={loading} className="w-full bg-green-500 text-white cursor-pointer" onClick={handleClick}>{loading ? '加载中...' : '发起请求'}
        </Button>
    </div>
)

}
